 56→	async function loadData() {
 57→		loading = true;
 58→		error = '';
 59→
 60→		try {
 61→			const [statusResult, defsResult] = await Promise.all([
 62→				fetchAgentStatus(),
 63→				fetchAgentDefinitions()
 64→			]);
 65→			dispatchStatus = statusResult;
 66→			agentDefinitions = defsResult.items;
 67→
 68→			// Pre-populate completed counts from API (server-side aggregation from session history)
 69→			const initial: Record<string, number> = {};
 70→			for (const def of statusResult.agent_definitions) {
 71→				if (def.completed_sessions != null && def.completed_sessions > 0) {
 72→					initial[def.id] = def.completed_sessions;
 73→				}
 74→			}
 75→			completedCounts = initial;
 76→		} catch (err) {
 77→			error = err instanceof Error ? err.message : 'Failed to load agent data';
 78→			console.error('Error loading agent data:', err);
 79→		} finally {
 80→			loading = false;
 81→		}
 82→	}
