 84→	async function handleStartDispatch() {
 85→		if (isStaticMode()) return;
 86→		isToggling = true;
 87→		error = '';
 88→
 89→		try {
 90→			const result = await controlDispatch('start');
 91→			// Refresh full status after toggle
 92→			dispatchStatus = await fetchAgentStatus();
 93→		} catch (err) {
 94→			if (err instanceof ReadOnlyModeError) {
 95→				error = err.message;
 96→			} else {
 97→				error = err instanceof Error ? err.message : 'Failed to start dispatch';
 98→			}
 99→		} finally {
100→			isToggling = false;
101→		}
102→	}
103→
104→	async function handleStopDispatch() {
105→		if (isStaticMode()) return;
106→		isToggling = true;
107→		error = '';
108→
109→		try {
110→			const result = await controlDispatch('stop');
111→			// Refresh full status after toggle
112→			dispatchStatus = await fetchAgentStatus();
113→		} catch (err) {
114→			if (err instanceof ReadOnlyModeError) {
115→				error = err.message;
116→			} else {
117→				error = err instanceof Error ? err.message : 'Failed to stop dispatch';
118→			}
119→		} finally {
120→			isToggling = false;
121→		}
122→	}
123→
124→	function handleAgentEvent(event: any) {
125→		if (event.event === 'agent_invocation') {
126→			const data = event.data;
127→			if (data.status === 'completed' || data.status === 'failed') {
128→				completedCounts = {
129→					...completedCounts,
130→					[data.agent_id]: (completedCounts[data.agent_id] || 0) + 1
131→				};
132→			}
133→			// Announce change to screen readers
134→			const agentLabel = data.agent_id || 'Agent';
135→			if (data.status === 'started') {
136→				invocationAnnouncement = `${agentLabel} invocation started`;
137→			} else if (data.status === 'completed') {
138→				invocationAnnouncement = `${agentLabel} invocation completed`;
139→			} else if (data.status === 'failed') {
140→				invocationAnnouncement = `${agentLabel} invocation failed`;
141→			}
142→			// Refresh status to update active invocations
143→			fetchAgentStatus()
144→				.then((status) => {
145→					dispatchStatus = status;
146→				})
147→				.catch((err) => console.error('Error refreshing agent status:', err));
148→		}
149→	}
