    29→	let isToggling = $state(false);
    30→
    31→	// Screen reader announcement for live invocation updates
    32→	let invocationAnnouncement = $state('');
    33→
    34→	// Track completed invocations per agent (incremented by WebSocket events)
    35→	let completedCounts = $state<Record<string, number>>({});
    36→
    37→	// Derive active counts per agent from dispatch status
    38→	let activeCounts = $derived.by(() => {
    39→		const counts: Record<string, number> = {};
    40→		if (dispatchStatus?.active_invocations) {
    41→			for (const inv of dispatchStatus.active_invocations) {
    42→				counts[inv.agent_id] = (counts[inv.agent_id] || 0) + 1;
    43→			}
    44→		}
    45→		return counts;
    46→	});
    47→
    48→	// Reload on project change
    49→	$effect(() => {
    50→		const version = getProjectVersion();
    51→		if (version > 0) {
    52→			loadData();
    53→		}
    54→	});
    55→
    56→	async function loadData() {
    57→		loading = true;
    58→		error = '';
    59→
    60→		try {
    61→			const [statusResult, defsResult] = await Promise.all([
    62→				fetchAgentStatus(),
    63→				fetchAgentDefinitions()
    64→			]);
    65→			dispatchStatus = statusResult;
    66→			agentDefinitions = defsResult.items;
    67→
    68→			// Pre-populate completed counts from API (server-side aggregation from session history)
    69→			const initial: Record<string, number> = {};
    70→			for (const def of statusResult.agent_definitions) {
    71→				if (def.completed_sessions != null && def.completed_sessions > 0) {
    72→					initial[def.id] = def.completed_sessions;
    73→				}
    74→			}
    75→			completedCounts = initial;
    76→		} catch (err) {
    77→			error = err instanceof Error ? err.message : 'Failed to load agent data';
    78→			console.error('Error loading agent data:', err);
    79→		} finally {
    80→			loading = false;
    81→		}
    82→	}
    83→
    84→	async function handleStartDispatch() {
    85→		if (isStaticMode()) return;
    86→		isToggling = true;
    87→		error = '';
    88→
    89→		try {
    90→			const result = await controlDispatch('start');
    91→			// Refresh full status after toggle
    92→			dispatchStatus = await fetchAgentStatus();
    93→		} catch (err) {
    94→			if (err instanceof ReadOnlyModeError) {
    95→				error = err.message;
    96→			} else {
    97→				error = err instanceof Error ? err.message : 'Failed to start dispatch';
    98→			}
    99→		} finally {
   100→			isToggling = false;
   101→		}
   102→	}
   103→
   104→	async function handleStopDispatch() {
   105→		if (isStaticMode()) return;
   106→		isToggling = true;
   107→		error = '';
   108→
   109→		try {
   110→			const result = await controlDispatch('stop');
   111→			// Refresh full status after toggle
   112→			dispatchStatus = await fetchAgentStatus();
   113→		} catch (err) {
   114→			if (err instanceof ReadOnlyModeError) {
   115→				error = err.message;
   116→			} else {
   117→				error = err instanceof Error ? err.message : 'Failed to stop dispatch';
   118→			}
   119→		} finally {
   120→			isToggling = false;
   121→		}
   122→	}
