 26→import { commitIfShadow } from '../../parser/shadow.js';
 27→
 28→interface MetaRouteOptions {}
 29→
 30→export function createMetaRoutes(options: MetaRouteOptions = {}) {
 31→  // No closure-scoped kspecDir needed - comes from middleware
 32→
 33→  return new Elysia({ prefix: '/api/meta' })
 34→    // AC: @api-contract ac-15 - Get session context
 35→    .get('/session', async ({ projectContext }) => {
 36→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 37→      const ctx = await initContext(projectContext.path);
 38→      const session = await loadSessionContext(ctx);
 39→
 40→      // AC: @api-contract ac-15 - Return session context (focus, threads, questions)
 41→      return {
 42→        focus: session.focus,
 43→        threads: session.threads || [],
 44→        questions: session.questions || [],
 45→        updated_at: session.updated_at,
 46→      };
 47→    })
 48→
 49→    // AC: @api-contract ac-16 - List agents
 50→    .get('/agents', async ({ projectContext }) => {
 51→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
 52→      const ctx = await initContext(projectContext.path);
 53→      const meta = await loadMetaContext(ctx);
 54→
 55→      // AC: @api-contract ac-16 - Return all defined agents
 56→      const agents = meta.agents;
 57→
 58→      return {
 59→        items: agents,
 60→        total: agents.length,
 61→      };
 62→    })
 63→
 64→    // AC: @ui-agent-dispatch ac-4 - Update agent definition
 65→    .patch(
 66→      '/agents/:id',
 67→      async ({ params, body, projectContext }) => {
 68→        const ctx = await initContext(projectContext.path);
 69→        const meta = await loadMetaContext(ctx);
 70→
 71→        // Find the agent by id
 72→        const agent = meta.agents.find((a) => a.id === params.id);
 73→        if (!agent) {
 74→          throw new Error(`Agent not found: ${params.id}`);
 75→        }
 76→
 77→        // Apply partial updates from body
 78→        const updated = { ...agent, ...body };
 79→
 80→        await saveMetaItem(ctx, updated, 'agent');
 81→        await commitIfShadow(ctx.shadow, `meta: update agent ${params.id}`);
 82→
 83→        return updated;
 84→      },
 85→      {
 86→        params: t.Object({
 87→          id: t.String(),
 88→        }),
 89→        body: t.Object({
 90→          name: t.Optional(t.String()),
 91→          description: t.Optional(t.String()),
 92→          adapter: t.Optional(t.String()),
 93→          dispatch: t.Optional(
 94→            t.Array(
 95→              t.Object({
 96→                on: t.String(),
 97→                filter: t.Optional(
 98→                  t.Object({
 99→                    automation: t.Optional(t.String()),
100→                    tags: t.Optional(t.Array(t.String())),
101→                    priority: t.Optional(t.Number()),
102→                  })
103→                ),
104→              })
105→            )
106→          ),
107→          capabilities: t.Optional(t.Array(t.String())),
108→          tools: t.Optional(t.Array(t.String())),
109→          skills: t.Optional(t.Array(t.String())),
110→          budget: t.Optional(
111→            t.Object({
112→              max_tasks: t.Optional(t.Number()),
113→              max_retries: t.Optional(t.Number()),
114→              timeout_minutes: t.Optional(t.Number()),
115→            })
116→          ),
117→          concurrency: t.Optional(
118→            t.Object({
119→              max_concurrent: t.Optional(t.Number()),
120→            })
121→          ),
122→          auto_approve: t.Optional(t.Boolean()),
123→          prompt_template: t.Optional(t.String()),
124→        }),
125→      }
126→    )
127→
128→    // AC: @api-contract ac-17 - List workflows
129→    .get('/workflows', async ({ projectContext }) => {
130→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
131→      const ctx = await initContext(projectContext.path);
132→      const meta = await loadMetaContext(ctx);
133→
134→      // AC: @api-contract ac-17 - Return all defined workflows
135→      const workflows = meta.workflows;
136→
137→      return {
138→        items: workflows,
139→        total: workflows.length,
140→      };
141→    })
142→
143→    // AC: @api-contract ac-18 - List observations with filter
144→    .get(
145→      '/observations',
146→      async ({ query, projectContext }) => {
147→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
148→        const ctx = await initContext(projectContext.path);
149→        const meta = await loadMetaContext(ctx);
150→
151→        // Start with all observations
152→        let filtered = meta.observations || [];
153→
154→        // AC: @api-contract ac-18 - Filter by resolved status
155→        if (query.resolved !== undefined) {
156→          const resolvedFilter = query.resolved === 'true';
157→          filtered = filtered.filter((obs) => {
158→            const isResolved = !!obs.resolved_at;
159→            return isResolved === resolvedFilter;
160→          });
161→        }
162→
163→        // Optional type filter (not in ACs but useful)
164→        if (query.type) {
165→          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
166→          filtered = filtered.filter((obs) => typeFilters.includes(obs.type));
167→        }
168→
169→        // Sort by created_at descending (newest first)
170→        const sorted = [...filtered].sort(
171→          (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
172→        );
173→
174→        return {
175→          items: sorted,
176→          total: sorted.length,
177→        };
178→      },
179→      {
180→        query: t.Object({
181→          resolved: t.Optional(t.String()),
182→          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
183→        }),
184→      }
185→    );
186→}
